INSERT INTO knowledge (knowledge_id, kb_number, title, body, state, visibility, owner_id, created_at, updated_at, org_id) VALUES (1242, 'KB-HR-HANDOFF-042', 'Manager Handoff Selection Standard', 'R1 For an Office Based employee select calendar cal_hr_handoff_42 event evt_handoff_core_42 named Manager Handoff - Core. R2 For an IT Support employee select calendar cal_hr_handoff_42 event evt_handoff_restricted_42 named Manager Handoff - Restricted. R3 R2 overrides R1. R4 Patch only the selected event so its sole attendee is the reporting manager email, then read the event back before sending email. R5 Open one case with short description Manager handoff for Nora Patel, status ready, priority high, source email, and Center of Excellence Workforce Administration.', 'published', 'internal', 1200, '2026-07-01 08:00:00', '2026-07-01 08:00:00', 1200);
